-- Автопостинг, крок 5: автоплан місяця і підготовка ідей у фоні
INSERT INTO changelog (title, body, created_at) VALUES ('Автопостинг: автоплан місяця', 'Контент → План → «Джері, розплануй місяць»: система сама розкладає слоти за частотою (Налаштування студії: скільки Reels/каруселей/сторіс на тиждень, дні й час), рубрики — за частками зі Стратегії; Джері дає теми тижнів, тему і хук кожного поста і підбирає кадри з матеріалів (тільки реальні рендери й планування, без повторів у сусідніх постах), враховуючи аналіз акаунта і минулі теми. Пости зʼявляються в календарі як «Ідеї». «Підготувати ідеї» — у фоні пише тексти і збирає всі ідеї місяця (сторіс, каруселі, Reels), сторінка оновлюється сама; готові пости — у «Пости» → «Готується», переглядаєш і шлеш на апрув. Галочка «замінити ідеї автоплану» прибирає незаймані ідеї автоплану і планує заново. Вже заплановане вручну не чіпається і враховується в частоті.', datetime('now'));
